#include <iostream>
using namespace std;

int main() {
    int x[6], total = 0;
    for (int &v : x) {
        cin >> v;
        total += v;
    }

    if (total % 3 != 0) {
        cout << 'N' << '\n';
        return 0;
    }

    int target = total / 3;

    for (int i = 0; i < 6; ++i) {
        if (x[i] != target) continue;

        for (int j = 0; j < 6; ++j) {
            if (j == i) continue;

            for (int k = j + 1; k < 6; ++k) {
                if (k != i && x[j] + x[k] == target) {
                    cout << 'S' << '\n';
                    return 0;
                }
            }
        }
    }

    cout << 'N' << '\n';
    return 0;
}
